{
  "name": "tenants.add-user-to-tenant",
  "kind": "write",
  "description": "Add a user to an active tenant with a role. Allowed for a global administrator or a TenantOwner of the tenant; if the tenant has never had a member, any caller may add its first member with any role. A user who is already a member is rejected; use tenants.change-user-role to change an existing member\u0027s role.",
  "schema": {
    "type": "object",
    "properties": {
      "TenantId": {
        "type": "string",
        "description": "Identifier of the tenant to add the user to."
      },
      "UserId": {
        "type": "string",
        "description": "Identifier of the user to add: the subject (sub) claim the identity provider issues for that user. It is not checked against the identity provider."
      },
      "Role": {
        "enum": [
          "Unknown",
          "TenantOwner",
          "TenantContributor",
          "TenantReader"
        ],
        "description": "Role to grant. Every role can read the tenant and its members; TenantContributor can also update its name and description; TenantOwner can also manage its members, roles and configuration. Unknown is rejected."
      }
    },
    "required": [
      "TenantId",
      "UserId",
      "Role"
    ],
    "additionalProperties": false
  },
  "example": {
    "TenantId": "acme",
    "UserId": "8d3f2a61-5b7e-4c0a-9e21-3f4b6c7d8e90",
    "Role": "TenantContributor"
  },
  "envelope": {
    "fixedTenant": "system",
    "aggregateIdRequired": false,
    "idempotencyKeyRequired": false,
    "arguments": [
      "aggregateId",
      "correlationId",
      "idempotencyKey",
      "extensions"
    ]
  },
  "lintFindings": [],
  "submittable": false,
  "reason": "configuration_invalid"
}
